describe('dynamic tools', () => {
  const registry = new ToolRegistry();
  const schema = {
    type: 'object',
    properties: {foo: {type: 'string'}},
    required: ['foo'],
  };
  const executor = jest.fn(async () => 'ok');

  const registerWithSchema = (s: Record<string, unknown>) =>
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'desc',
        inputSchema: s,
      }),
      executor
    );

