    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L20))
    registerWithSchema(schema);

    await registry.execute('dynamic_tool', {foo: 'bar'});
    await registry.execute('dynamic_tool', {foo: 'baz'});

    expect(executor).toHaveBeenCalledTimes(2);
  });

  it('recompiles for dynamic tools when schema object reference changes', async () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L20))
    registerWithSchema(schema);
    await registry.execute('dynamic_tool', {foo: 'bar'});

    const schema2 = {
      type: 'object',
      properties: {foo: {type: 'string'}},
      required: ['foo'],
    };
    registerWithSchema(schema2);

    await registry.execute('dynamic_tool', {foo: 'qux'});
    expect(executor).toHaveBeenCalledTimes(4); // 2 from previous test + 2 in this one
  });
});

