describe('dynamic tools', () => {
  const setupDynamic = () => {
    const registry = new ToolRegistry();
    const schema = {
      type: 'object',
      properties: {foo: {type: 'string'}},
      required: ['foo'],
    };
    const executor = jest.fn(async () => 'ok');
